final class Item {
    private final List<String> tags;
    Item(List<String> tags) { this.tags = tags; }
    List<String> tags() { return List.copyOf(tags); }
}
// in main:
var src = new ArrayList<>(List.of("new"));
var item = new Item(src);
src.add("sale");
System.out.println(item.tags());
